  "findings": [
    {
      "claim": "The task contains two independently maintainable provider specifications that can be investigated in parallel.",
      "evidence": [
        "delegation/delegation.md § Contribution gate: 'two or more source fields can be investigated independently' qualifies the task for delegation.",
        "delegation/delegation.md § Topology table: 'Independent sources → parallel investigators (read-only or isolated sources)' matches the two read-only provider specs."
      ],
      "consequence": "Two parallel read-only investigation workers are the correct first layer; each owns one provider spec and returns compressed evidence."
    },
    {
      "claim": "A fresh reviewer is required because the comparison is consequential and producer bias is decision-relevant.",
      "evidence": [
        "delegation/delegation.md § Contribution gate: 'a non-producing reviewer can expose a consequential producer-correlated failure'.",
        "delegation/delegation.md § Topology table: 'Consequential candidate → maker then fresh reviewer (reviewer stays read-only)'."
      ],
      "consequence": "After the two investigation workers return, a separate reviewer worker receives the exact claims, acceptance contract, and evidence boundary, but no producer history. It can reject or qualify but cannot accept, merge, or publish."
